<div class="page-title-row"><div><span class="eyebrow">THẺ ĐỘC GIẢ</span><h1><?= e($reader['full_name']) ?></h1><p><?= e($reader['card_number']) ?> · <?= $reader['is_active']?'Đang hoạt động':'Ngừng hoạt động' ?> · Hết hạn <?= e(format_date($reader['expires_on'])) ?></p></div><a class="button button-outline" href="<?= e(url('/admin/readers')) ?>">Danh sách độc giả</a></div>
<section class="panel"><h2>Lịch sử mượn</h2><div class="table-scroll"><table><thead><tr><th>Phiếu</th><th>Sách / bản sao</th><th>Ngày mượn</th><th>Hạn trả</th><th>Ngày trả</th><th>Gia hạn</th></tr></thead><tbody><?php foreach($loans as $loan): ?><tr><td><?= e($loan['loan_code']) ?></td><td><?= book_thumbnail($loan) ?><?= e($loan['book_title']) ?><small><?= e($loan['copy_code']) ?></small></td><td><?= e(format_date($loan['item_borrowed_at'])) ?></td><td><?= e(format_date($loan['due_at'])) ?></td><td><?= e(format_date($loan['returned_at'])) ?></td><td><?= (int)$loan['renewal_count'] ?></td></tr><?php endforeach; ?><?php if(!$loans): ?><tr><td colspan="6">Chưa có lịch sử mượn.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><h2>Phí và dư nợ</h2><div class="table-scroll"><table><thead><tr><th>Bản sao</th><th>Nội dung</th><th>Phí</th><th>Đã thu</th><th>Miễn giảm</th><th>Còn nợ</th></tr></thead><tbody><?php foreach($charges as $charge): ?><tr><td><?= e($charge['copy_code']) ?></td><td><?= e($charge['description']) ?></td><td><?= number_format((float)$charge['amount']) ?></td><td><?= number_format((float)$charge['paid_amount']) ?></td><td><?= number_format((float)$charge['waived_amount']) ?></td><td><?= number_format((float)$charge['balance']) ?></td></tr><?php endforeach; ?><?php if(!$charges): ?><tr><td colspan="6">Không có khoản phí.</td></tr><?php endif; ?></tbody></table></div></section>
